// Swagger / OpenAPI 3.0 configuration
const swaggerJSDoc = require('swagger-jsdoc');
const swaggerUi = require('swagger-ui-express');

const options = {
  definition: {
    openapi: '3.0.0',
    info: {
      title: 'Advanced Orders & Inventory Management API - Lab 3 Homework',
      version: '1.0.0',
      description:
        'Node.js + Express + MySQL (mysql2/promise) orders API with atomic transactions, ' +
        'inventory control and sales analytics. Interactive docs generated by swagger-jsdoc.'
    },
    servers: [
      {
        url: 'http://localhost:3000/api',
        description: 'Development Local Server'
      }
    ]
  },
  // Files scanned for @swagger comments (relative to the folder you start the server from)
  apis: ['./routes/*.js']
};

const swaggerSpec = swaggerJSDoc(options);

const setupSwagger = (app, port = process.env.PORT || 3000) => {
  app.use('/api-docs', swaggerUi.serve, swaggerUi.setup(swaggerSpec));
  console.log(`Swagger UI documentation is ready at: http://localhost:${port}/api-docs`);
};

module.exports = setupSwagger;
